Split `IMachine` into smaller, role-specific interfaces. For example:
```java
interface IStartStoppable { void start(); void stop(); }
interface IPrintable { void print(); }
interface IScannable { void scan(); }

// BasicPrinter only implements what it needs
class BasicPrinter implements IStartStoppable, IPrintable {
    public void start() { /* ... */ }
    public void stop() { /* ... */ }
    public void print() { /* ... */ }
}

// A MultifunctionDevice could implement all three
class MultifunctionDevice implements IStartStoppable, IPrintable, IScannable {
    // ... implementations ...
}
```

```java
interface IDepositable {
    void deposit(double amount);
}

interface IWithdrawable {
    void withdraw(double amount);
}

interface IInterestCalculable {
    double calculateInterest();
}

interface ITransactionHistoryViewable {
    List<Transaction> viewTransactionHistory();
}

// SavingsAccount implements all necessary interfaces
class SavingsAccount implements IDepositable, IWithdrawable, IInterestCalculable, ITransactionHistoryViewable {
    // ... implementations ...
}

// CheckingAccount implements only what it needs
class CheckingAccount implements IDepositable, IWithdrawable, ITransactionHistoryViewable {
    // ... implementations ...
}
```
